-- Pandaria SmartAI (B20): pandaria_548 world DB scripts for creatures and spawns that have no script here and none in LoA either.
-- Generated by skyfire_port_plan/tools/dbcompare/d23_smart_scripts.py then d24_smart_scripts_translated.py, run with the pandaria DB in place of LoA.

-- Scripted behaviour (SmartAI) from pandaria's world DB for creatures that had no script (B20, D23 rules):
-- 155 creature scripts and 9 single-spawn scripts, 524 rows, 15 timed action lists.
-- Generated by skyfire_port_plan/tools/dbcompare/d23_smart_scripts.py. Safe to run twice.

-- Scripts. A script is only added while that creature, spawn or action list still has no rows.
DROP TEMPORARY TABLE IF EXISTS `tmp_d23_smart`;
CREATE TEMPORARY TABLE `tmp_d23_smart` LIKE `smart_scripts`;
DELETE t FROM `tmp_d23_smart` t JOIN (SELECT DISTINCT `entryorguid`, `source_type` FROM `smart_scripts`) x ON x.`entryorguid` = t.`entryorguid` AND x.`source_type` = t.`source_type`;
DROP TEMPORARY TABLE `tmp_d23_smart`;

-- Paths those scripts walk: 12 points on 2 paths
DELETE FROM `waypoints` WHERE `entry` IN (42324,68705);

-- Lines those scripts say: 73 rows in 51 text groups

