INSERT IGNORE INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(3063,0,0,'Hulfnar! Thontek! Stand and address me.',12,3,100,1,0,0,'Krang Stonehoof'),
(3063,1,0,'I want you both to demonstrate the techniques I have taught you for the benefit of the younger students here. Ready... begin!',12,3,100,1,0,0,'Krang Stonehoof'),
(3063,2,0,'Enough talk you two! Commence fighting!',12,3,100,22,0,0,'Krang Stonehoof'),
(3063,3,0,'Now that\'s a War Stomp! Good job!',12,3,100,21,0,0,'Krang Stonehoof'),
(3063,3,1,'That\'s how it\'s done class! You better be paying attention!',12,3,100,21,0,0,'Krang Stonehoof'),
(3063,3,2,'Now that\'s putting your hoof down!',12,3,100,21,0,0,'Krang Stonehoof'),
(3063,4,0,'Ish nu! That\'s enough!',12,3,100,1,0,0,'Krang Stonehoof'),
(3063,5,0,'Well Done!',12,3,100,1,0,6575,'Krang Stonehoof'),
(3063,6,0,'Good, good. Now bow to each other.',12,3,100,1,0,0,'Krang Stonehoof'),
(3063,7,0,'Now bow to me.',12,3,100,1,0,0,'Krang Stonehoof'),
(3063,8,0,'Good job you two. Now go have a seat.',12,3,100,1,0,0,'Krang Stonehoof'),
(21514,0,0,'Who dares defile the altar of Gorgrom the Dragon-Eater?',14,0,100,0,0,0,''),
(21514,1,0,'I will crush it and flay it and eat its meat and crack its bones one by one when I am done.',14,0,100,0,0,0,''),
(23028,0,0,'I\'ve seen female Gnomes hit harder than you!',14,0,100,0,0,0,'Bonechewer Taskmaster'),
(23028,0,1,'If you don\'t start throwing some real punches, you\'ll be cleaning the drake stalls for a year!',14,0,100,0,0,0,'Bonechewer Taskmaster'),
(23028,0,2,'Stop your slacking and fight like a true fel orc!',14,0,100,0,0,0,'Bonechewer Taskmaster'),
(23028,0,3,'You call that an offense? I\'ve seen more offensive tallstriders!',14,0,100,0,0,0,'Bonechewer Taskmaster'),
(23028,1,0,'%s becomes increasingly enraged as he sees his allies fall in battle!',16,0,100,0,0,0,'Bonechewer Taskmaster'),
(23698,0,0,'Uh oh...',12,0,100,0,0,0,'Drunken Brewfest Reveler'),
(23698,0,1,'Good times! <hic!>',12,0,100,0,0,0,'Drunken Brewfest Reveler'),
(23698,0,2,'What\'s all the fuss about here?',12,0,100,0,0,0,'Drunken Brewfest Reveler'),
(23698,0,3,'The besht part about drinking is pretending to be drunk... I\'m jusht pretending guys.',12,0,100,0,0,0,'Drunken Brewfest Reveler'),
(23698,0,4,'Hey fellas!  How\'s it going?',12,0,100,0,0,0,'Drunken Brewfest Reveler'),
(23698,0,5,'Hey! Anyone shee that cute blond dwarf?  I shwear they were jusht here...',12,0,100,0,0,0,'Drunken Brewfest Reveler'),
(23698,0,6,'Hey! Lishten up!  I\'ve got... I have something important to talk about!  Shee... Wait... What wash I shaying?  Something aboutsh boats and floating... Yeah! Sho don\'t float on a boat... Thank you...',12,0,100,0,0,0,'Drunken Brewfest Reveler'),
(34519,0,0,'Give toy back!',12,0,100,1,0,0,'Oracle Orphan'),
(34519,1,0,'Stop!',12,0,100,1,0,0,'Oracle Orphan'),
(34519,2,0,'We tell orphan matron on you!',12,0,100,1,0,0,'Oracle Orphan'),
(36712,0,0,'Squealer take this land! Tauren will burn!',12,0,100,0,0,0,'Chief Squealer Thornmantle'),
(37067,0,1,'I wasn\'t ready to die in a marsh. Thanks again!',12,0,100,0,0,0,'Crash Survivor'),
(37067,0,2,'Let\'s get out of this marsh!',12,0,100,0,0,0,'Crash Survivor'),
(37067,0,3,'Time to run!',12,0,100,0,0,0,'Crash Survivor'),
(37067,0,4,'You got here just in time. Thanks!',12,0,100,0,0,0,'Crash Survivor'),
(45205,0,0,'%s attempts to run away in fear!',16,0,100,0,0,0,'Sultan Oogah'),
(45772,0,0,'%s attempts to run away in fear!',16,0,100,0,0,0,'General Ammantep'),
(46590,0,0,'%s attempts to run away in fear',16,0,100,0,0,0,'Crazed Digger'),
(46617,0,0,'Hubba-hubba!',12,0,50,0,0,0,'Cursed Engineer'),
(46617,0,1,'You could bounce a washer off those legs!',12,0,50,0,0,0,'Cursed Engineer'),
(46617,0,2,'Weaponized sharks? Why didn\'t I think of that!',12,0,50,0,0,0,'Cursed Engineer'),
(46617,0,3,'ROCK ON!',12,0,50,0,0,0,'Cursed Engineer'),
(46617,0,4,'So... EPIC!',12,0,50,0,0,0,'Cursed Engineer'),
