(68336,0,0,'Use the Kor\'kron Disguise, then search for intel in the middle of Garrosh\'ar Advance.',42,0,100,0,0,0,''),
(68336,1,0,'I am losing patience, Shan Kien. Tell me where I can find the Divine Bell!',12,0,100,5,0,0,''),
(68336,2,0,'Ishi, draw your blade. A few carefully delivered cuts will change his mind.',12,0,100,1,0,0,''),
(68336,3,0,'Speak, then!',12,0,100,1,0,0,''),
(68375,0,0,'WHAT?! You saw where the mogu hid the Divine Bell? I\'ll alert Lion\'s Landing immediately. We gotta get this thing before Garrosh. We\'ll contact you as soon as we find it!',12,0,100,5,0,0,'');
