INSERT IGNORE INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(24806,0,0,'Launching.',12,0,100,0,0,0,'Iron Rune Construct'),
(25258,0,0,'One last drink before we head to the front?',12,7,100,1,0,0,'Footman Rob'),
(25258,1,0,'Barkeep! Bring out your strongest ale. We\'re off to the front.',12,7,100,1,0,0,'Footman Rob'),
(25258,2,0,'You\'ll surely make an exception for us, eh? We might not come back.',12,7,100,1,0,0,'Footman Rob'),
(25258,3,0,'I guess that\'s it then. Off we go.',12,7,100,1,0,0,'Footman Rob'),
(25259,0,0,'Sure, why not?',12,7,100,6,0,0,'Footman George'),
(25261,0,0,'That was the worst beer I\'ve ever had.',12,7,100,0,0,0,'Footman Chuck'),
(27713,0,0,'What is it?',12,0,100,0,0,0,'7th Legion Elite'),
(27713,0,1,'Is this the end? If we stop this monster now, is victory assured at the Wrathgate?',12,0,100,0,0,0,'7th Legion Elite'),
(27713,0,2,'Let it be known that it has been an honor and a privilege fighting alongside all of you. ',12,0,100,0,0,0,'7th Legion Elite'),
(27713,0,3,'Death comes for us all eventually, but sometimes it comes a little faster than anticipated. Today we call that blind heroics... Tomorrow someone may call it stupidity.  ',12,0,100,0,0,0,'7th Legion Elite'),
(27713,0,4,'Come on... Let\'s get this over with! ',12,0,100,0,0,0,'7th Legion Elite'),
(27713,0,5,'It looks like a gateway to hell!',12,0,100,0,0,0,'7th Legion Elite'),
(27713,0,6,'I\'m getting a little worried. Where is this hero that is supposed to lead us into battle?',12,0,100,0,0,0,'7th Legion Elite'),
(27713,0,7,'If I don\'t make it back to Wintergarde, let my family know that I did my best and that I love them...',12,0,100,0,0,0,'7th Legion Elite'),
(27857,0,0,'Steel yourselves, soldiers. $n has provided us with the final piece of this puzzle. The dread lich, Thel\'zan, will soon come out of hiding, only to be rendered powerless against us!',12,0,100,0,0,0,'Legion Commander Yorik'),
(27857,1,0,'It is this phylactery - Thel\'zan\'s phylactery - that is the key to victory!',12,0,100,0,0,0,'Legion Commander Yorik'),
(27858,4,0,'Victory for the Alliance!',14,0,100,0,0,0,'Highlord Bolvar Fordragon'),
(27858,5,0,'You have saved Wintergarde! With Thel\'zan\'s filth washed away, the 7th Legion will easily clean up the remaining Scourge. When you are done here, report to Angrathar!',12,0,100,0,0,0,'Highlord Bolvar Fordragon'),
(46041,0,0,'You will be punished for this transgression, thief!',14,0,100,0,0,0,''),
(46042,0,0,'You will be punished for this transgression, thief!',14,0,100,0,0,0,''),
(64506,1,0,'',12,0,100,0,0,27381,'Aysa Cloudsinger'),
(64506,1,1,'',12,0,100,0,0,27382,'Aysa Cloudsinger');
